end
local function makeLabel(parent, size, x, y, ax, ay, color)
    local lb = Label(FONT, size)
    if lb == nil then
        return nil
    end
    lb.anchor = Vec2(ax, ay)
    lb.position = Vec2(x, y)
    lb.color = Color(color.r, color.g, color.b, color.a)
    lb:addTo(parent)
    return lb
end
local function setText(lb, text)
    if lb ~= nil and lb.text ~= text then
        lb.text = text
    end
end
