function NotebookUI.prototype.makeIcon(self, path, x, y, h)
    local tex = Texture2D(path)
    if tex == nil then
        return nil
    end
    local sp = Sprite(tex)
    if sp == nil then
        return nil
    end
    sp.scaleX = h / tex.height
    sp.scaleY = h / tex.height
    sp.position = Vec2(x, y)
    sp:addTo(self.root)
    return sp
end
function NotebookUI.prototype.debugIconCount(self)
    local n = 0
    if self.iconMoon ~= nil then
        n = n + 1
    end
    if self.iconToken ~= nil then
        n = n + 1
    end
    return n
end
function NotebookUI.prototype.toggle(self)
    self.openFlag = not self.openFlag
    self.root.visible = self.openFlag
end
function NotebookUI.prototype.isOpen(self)
    return self.openFlag
end
function NotebookUI.prototype.update(self, _dt, state)
    if not self.openFlag then
        return
    end
    local w = View.size.width
    local h = View.size.height
    self.draw:clear()
    self.draw:drawPolygon(
        {
            Vec2(-440, -250),
            Vec2(440, -250),
            Vec2(440, 250),
            Vec2(-440, 250)
        },
        col(ink(Palette.paper.r, Palette.paper.g, Palette.paper.b, 250)),
        2,
        col(Palette.inkDark)
    )
    self.draw:drawPolygon(
        {
            Vec2(-428, -238),
            Vec2(428, -238),
            Vec2(428, 238),
            Vec2(-428, 238)
        },
        col(ink(0, 0, 0, 0)),
        1,
        col(Palette.goldSoft)
    )
    self.draw:drawSegment(
        Vec2(-172, -210),
        Vec2(-172, 190),
        1,
        col(Palette.inkFaint)
    )
    self.draw:drawSegment(
        Vec2(48, -210),
        Vec2(48, 190),
        1,
        col(Palette.inkFaint)
    )
    local phaseName = state.phaseIndex >= 0 and state.phaseIndex < #PHASE_NAMES and PHASE_NAMES[state.phaseIndex + 1] or ""
    setText(
        self.loopLb,
        ("第" .. tostring(state.loopIndex + 1)) .. "周目"
    )
    setText(self.phaseLb, "当前月相：" .. phaseName)
    local checkpointName = "未记录"
    do
        local i = 0
        while i < #Tower.checkpoints do
            if Tower.checkpoints[i + 1].id == state.currentCheckpointId then
                checkpointName = Tower.checkpoints[i + 1].label
                break
            end
            i = i + 1
        end
    end
    setText(self.checkLb, "检查点：" .. checkpointName)
    setText(
        self.stoneLb,
        "月石　x " .. tostring(state.moonstones)
    )
    setText(
        self.tokenLb,
        "旧物　x " .. tostring(state.tokens)
    )
    local total = #state.causalityLog
    local start = Math:max(0, total - #self.causeLbs)
    do
        local i = 0
        while i < #self.causeLbs do
            local idx = start + i
            if idx < total then
                setText(
                    self.causeLbs[i + 1],
                    (tostring(idx + 1) .. ". ") .. state.causalityLog[idx + 1]
                )
                self.causeLbs[i + 1].color = Color(Palette.inkSoft.r, Palette.inkSoft.g, Palette.inkSoft.b, Palette.inkSoft.a)
            else
                setText(self.causeLbs[i + 1], "")
            end
            i = i + 1
        end
    end
    if self.iconMoon == nil then
        self.draw:drawDot(
            Vec2(-116, 92),
            7,
            col(Palette.moonCyan)
        )
        self.draw:drawDot(
            Vec2(-116, 92),
            10,
            col(Palette.moonCyanFaint)
        )
    end
    if self.iconToken == nil then
        self.draw:drawPolygon(
            {
                Vec2(-116, 62),
                Vec2(-108, 56),
                Vec2(-116, 50),
                Vec2(-124, 56)
            },
            col(Palette.vermilion)
        )
    end
    do
        local i = 0
        while i < #self.memoryLbs do
            local known = i < #MEMORIES_LIST and state.memories:indexOf(MEMORIES_LIST[i + 1]) >= 0
            local y = 92 - i * 36
            if known then
                self.draw:drawDot(
                    Vec2(102, y),
                    5,
                    col(Palette.inkDark)
                )
                setText(self.memoryLbs[i + 1], MEMORIES_LIST[i + 1])
                self.memoryLbs[i + 1].color = Color(Palette.inkSoft.r, Palette.inkSoft.g, Palette.inkSoft.b, Palette.inkSoft.a)
            else
                self.draw:drawPolygon(
                    {
                        Vec2(102, y + 6),
                        Vec2(108, y),
                        Vec2(102, y - 6),
                        Vec2(96, y)
                    },
                    col(ink(0, 0, 0, 0)),
                    1,
                    col(Palette.inkFaint)
                )
                setText(self.memoryLbs[i + 1], "？")
                self.memoryLbs[i + 1].color = Color(Palette.paleInkFar.r, Palette.paleInkFar.g, Palette.paleInkFar.b, Palette.paleInkFar.a)
            end
            i = i + 1
        end
    end
end
